// Input: deleted index + graph. Apply numerical interface only, not cube adjacency or catalogue labels.
use std::io::{self,BufRead};type A=[u32;27];
fn search(g:&A,p:u32,h:u32,k:u32,z:u32,e:u32,f:u32,tag:u32){if k==0{let mut cnt=[0;5];for (j,&v) in g.iter().enumerate(){if j==z as usize{continue}let n=(h&v).count_ones();if h>>j&1!=0{if !(3..=4).contains(&n){return}}else{if !(1..=2).contains(&n)||v.count_ones()<(if n==1{4}else{6}){return}}cnt[n as usize]+=1}if cnt==[0,6,12,6,2]{println!("{} {} {} {}",tag,e,f,h)}return}let mut m=p;while m.count_ones()>=k{let b=m&m.wrapping_neg();m^=b;search(g,m,h|b,k-1,z,e,f,tag)}}
fn main(){for line in io::stdin().lock().lines(){let vals:Vec<u32>=line.unwrap().split_whitespace().map(|v|v.parse().unwrap()).collect();let z=vals[0];let mut a=[0;27];a.copy_from_slice(&vals[1..28]);if vals.len()==29{let p=(0..27).filter(|&i|a[i].count_ones()==7).fold(0,|s,i|s|1<<i);search(&a,p,0,8,z,0,0,vals[28]);continue}let mut marks=vec![];for i in 0..27{for j in 0..i{if i!=z as usize&&j!=z as usize&&a[i]&a[j]==1<<z&&a[i]>>j&1==0{marks.push((i,j))}}}for t in 0..marks.len(){let(i,j)=marks[t];let e=1<<i|1<<j;for &(v,w) in &marks[..t]{let f=1<<v|1<<w;if e&f!=0{continue}if vals.len()>28 && !((e==vals[28]&&f==vals[29])||(e==vals[29]&&f==vals[28])){continue}let mut g=a;g[z as usize]=0;for h in &mut g{*h &=!(1<<z)}g[i]|=1<<j;g[j]|=1<<i;g[v]|=1<<w;g[w]|=1<<v;let p=(0..27).filter(|&i|g[i].count_ones()==7).fold(0,|s,i|s|1<<i);search(&g,p,0,8,z,e,f,if vals.len()>28{vals[30]}else{z})}}}}
